#!/bin/sh
# Flux Backup recovery kit: back up "borg" (borg) with plain borg, without Flux.
#
#   sh flux-backup.sh             make a new archive
#   sh flux-backup.sh --dry-run   only show what would be backed up
#
# Generated by Flux Backup 1.0.0. FLUX-RECOVERY.txt explains everything else.
set -eu

export BORG_REPO=/srv/tgt/flux-borg/fixture-host/root/borg/repo
[ -n "${BORG_PASSPHRASE:-}${BORG_PASSCOMMAND:-}" ] || export BORG_PASSCOMMAND='secret-tool lookup service flux-backup profile borg'

# --dry-run only shows what would be backed up; otherwise borg prints statistics.
MODE=--stats
if [ "${1:-}" = "--dry-run" ]; then MODE="--dry-run --list"; fi

# Exclusion patterns (borg --patterns-from syntax; the first matching pattern wins).
PATTERNS=$(mktemp)
trap 'rm -f "$PATTERNS"' EXIT
cat > "$PATTERNS" <<'FLUX_PATTERNS'
# Flux Backup: exclusion patterns for “borg” (borg)
# Borg patterns (borg create --patterns-from). The first pattern that matches a path
# decides: "! " leaves it out (and doesn't look inside), "+ " keeps it.
# Paths have no leading slash. "P sh": shell-style, ** matches across folders.
P sh

# The backup folders themselves:
! pp:srv/tgt/flux-borg
FLUX_PATTERNS

set +e
borg create --compression=zstd,3 --exclude-caches --patterns-from="$PATTERNS" $MODE \
    '::{now:%Y-%m-%d_%H-%M-%S}' \
    /srv/src
RC=$?
set -e
case $RC in
    0) ;;
    1) echo "borg finished with warnings (some files could not be read); the archive is usable." >&2 ;;
    *) echo "borg failed (exit $RC)." >&2
       exit "$RC" ;;
esac
